   147  // Decompress several hundred bytes by peeking at the file, which must be
   148  // positioned at the start of a GZIP block.
   149  static size_t decompress_peek(hFILE *fp, unsigned char *dest, size_t destsize)
   150  {
   151      unsigned char buffer[2048];
   152      z_stream zs;
   153      ssize_t npeek = hpeek(fp, buffer, sizeof buffer);
   154
   155      if (npeek < 0) return 0;
   156
   157      zs.zalloc = NULL;
   158      zs.zfree = NULL;
   159      zs.next_in = buffer;
   160      zs.avail_in = npeek;
   161      zs.next_out = dest;
   162      zs.avail_out = destsize;
   163      if (inflateInit2(&zs, 31) != Z_OK) return 0;
   164
   165      while (zs.total_out < destsize)
   166          if (inflate(&zs, Z_SYNC_FLUSH) != Z_OK) break;
   167
   168      destsize = zs.total_out;
   169      inflateEnd(&zs);
   170
   171      return destsize;
   172  }
