   174  // Parse "x.y" text, taking care because the string is not NUL-terminated
   175  // and filling in major/minor only when the digits are followed by a delimiter,
   176  // so we don't misread "1.10" as "1.1" due to reaching the end of the buffer.
   177  static void
   178  parse_version(htsFormat *fmt, const unsigned char *u, const unsigned char *ulim)
   179  {
   180      const char *s    = (const char *) u;
   181      const char *slim = (const char *) ulim;
   182      short v;
   183
   184      fmt->version.major = fmt->version.minor = -1;
   185
   186      for (v = 0; s < slim && isdigit_c(*s); s++)
   187          v = 10 * v + *s - '0';
   188
   189      if (s < slim) {
   190          fmt->version.major = v;
   191          if (*s == '.') {
   192              s++;
   193              for (v = 0; s < slim && isdigit_c(*s); s++)
   194                  v = 10 * v + *s - '0';
   195              if (s < slim)
   196                  fmt->version.minor = v;
   197          }
   198          else
   199              fmt->version.minor = 0;
   200      }
   201  }
